    if os.uname().machine not in ('x86_64', 'amd64'):
        raise ValueError('Publisher archive requires Linux x64')
    migrate_legacy_data(root)
    install_release(root, release(env.get('VERSION', '20.1.1')), 'ddnet', 'DDNet-Server',
