    names = {'data', 'maps', 'maps7', 'demos', 'autoexec_server.cfg', 'storage.cfg', 'myServerconfig.cfg'}
    names.update(p.name for p in root.iterdir() if p.is_file() and p.suffix in ('.sqlite', '.sqlite3', '.db'))
