    path.parent.mkdir(parents=True,exist_ok=True)
    previous=path.stat() if path.exists() else None
    if path.is_file() and path.read_bytes()==data:return
    fd,tmp=tempfile.mkstemp(prefix='.limbo-',dir=path.parent)
    try:
