def patch_properties(content,values):
    seen=set();lines=[];newline='\r\n' if '\r\n' in content else '\n'
    for line in content.splitlines(keepends=True):
        match=re.match(r'^(\s*)([^#!\s][^=]*?)(\s*=)([^\r\n]*)(\r?\n)?$',line)
