    root = Path(root).resolve()
    auto = choice({'AUTO_UPDATE': env.get('VOLTRA_STEAM_AUTO_UPDATE', env.get('AUTO_UPDATE', '1'))}, 'AUTO_UPDATE', '1', ('0', '1'))
