        'STEAM_USER', 'STEAM_PASS', 'STEAM_AUTH', 'SRCDS_BETAPASS', 'PLAYER_PASSWORD', 'DM_PASSWORD',
        'PYTHONPATH', 'PYTHONHOME', 'LD_PRELOAD')}
