        for key, item in value.items():
            if isinstance(item, str) and item and any(name in key.lower() for name in ('password', 'credential', 'token', 'secret')):
                result.append(item)
            result.extend(secret_values(item))
    elif isinstance(value, list):
        for item in value:
            result.extend(secret_values(item))
    return result


